using System.Text.Json;
using Ticketing.Domain.Ordering;

namespace Ticketing.Domain.Tests.Ordering;

public sealed class FractionalIndexTests
{
    /// <summary>11,000 (a, b, expected) cases generated by the npm package fractional-indexing@4.0.0, which the frontend uses.</summary>
    public static TheoryData<int> CompatibilityChunks() => [.. Enumerable.Range(0, 11)];

    private static readonly Lazy<string?[][]> Cases = new(() =>
        JsonSerializer.Deserialize<string?[][]>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "TestData", "fractional-indexing-cases.json")))!);

    [Theory]
    [MemberData(nameof(CompatibilityChunks))]
    public void KeyBetween_matches_the_npm_package(int chunk)
    {
        // Arrange
        var cases = Cases.Value.Skip(chunk * 1000).Take(1000).ToList();

        // Act
        var mismatches = cases.Where(c => FractionalIndex.KeyBetween(c[0], c[1]) != c[2]).ToList();

        // Assert
        Assert.Empty(mismatches);
    }

    [Theory]
    [InlineData(null, null, "a0")]
    [InlineData("a0", null, "a1")]
    [InlineData(null, "a0", "Zz")]
    [InlineData("a0", "a1", "a0V")]
    [InlineData("Zz", "a0", "ZzV")]
    public void KeyBetween_known_vectors(string? a, string? b, string expected) =>
        Assert.Equal(expected, FractionalIndex.KeyBetween(a, b));

    [Fact]
    public void KeyBetween_rejects_unordered_bounds() =>
        Assert.Throws<ArgumentException>(() => FractionalIndex.KeyBetween("a1", "a0"));

    [Theory]
    [InlineData(null, null, 5)]
    [InlineData("a0", null, 7)]
    [InlineData(null, "a0", 7)]
    [InlineData("a0", "a1", 10)]
    public void NKeysBetween_returns_strictly_ordered_keys_inside_the_bounds(string? a, string? b, int n)
    {
        // Act
        var keys = FractionalIndex.NKeysBetween(a, b, n);

        // Assert
        Assert.Equal(n, keys.Count);
        var bounded = new List<string?> { a }.Concat(keys).Append(b).ToList();
        for (var i = 1; i < bounded.Count; i++)
        {
            if (bounded[i - 1] is { } lower && bounded[i] is { } upper)
                Assert.True(string.CompareOrdinal(lower, upper) < 0, $"{lower} < {upper}");
        }
    }

    [Fact]
    public void Ranks_need_rebalancing_after_many_inserts_at_the_same_spot()
    {
        // Arrange
        var low = "a0";
        var high = "a1";

        // Act
        var steps = 0;
        while (!Ranks.NeedsRebalance(high = Ranks.Between(low, high)))
            steps++;

        // Assert
        Assert.True(steps > 50, $"Rebalance needed after only {steps} inserts.");
    }

    [Theory]
    [InlineData(0, 0)]
    [InlineData(4, 0)]
    [InlineData(4, 2)]
    [InlineData(4, 4)]
    [InlineData(500, 250)]
    public void PlanRebalance_keeps_order_and_leaves_a_slot(int existing, int insertIndex)
    {
        // Act
        var plan = Ranks.PlanRebalance(existing, insertIndex);

        // Assert
        var all = plan.ExistingRanks.ToList();
        all.Insert(insertIndex, plan.InsertedRank);
        Assert.Equal(existing, plan.ExistingRanks.Count);
        Assert.Equal(all.OrderBy(r => r, StringComparer.Ordinal), all);
        Assert.Equal(all.Count, all.Distinct().Count());
        Assert.All(all, r => Assert.True(r.Length <= Ranks.RebalanceThreshold));
    }
}
